// Browser-only, per-account presentation preference. No credentials or server writes.
const weights=new Set(['320','350','300']);
export function createAlbumFontWeight({getUserId,doc=document,storage=()=>localStorage}){
 const temporary=new Map();let control=null;
 const userId=()=>{const id=getUserId();return typeof id==='string'&&id.trim()&&id.length<=256?id:null;};
 const key=id=>'vinyl-room-album-font-weight-v1:'+encodeURIComponent(id);
 function read(){const id=userId();if(!id)return '320';if(temporary.has(id))return temporary.get(id);try{const value=storage().getItem(key(id));return weights.has(value)?value:'320';}catch{return '320';}}
 function apply(){const value=read();doc.documentElement.style.setProperty('--vr-user-font-weight',value);doc.documentElement.style.setProperty('--vr-album-text-weight',value);if(control){control.select.value=value;control.select.disabled=!userId()||userId()!==control.owner;}return value;}
 function set(value,expected=userId()){const id=userId();value=String(value);if(!id||id!==expected||!weights.has(value)){apply();return {applied:false,persisted:false};}temporary.set(id,value);let persisted=true;try{storage().setItem(key(id),value);}catch{persisted=false;}apply();return {applied:true,persisted};}
 function mount(container){container.querySelector('[data-album-font-weight-setting]')?.remove();const owner=userId(),box=doc.createElement('div');box.dataset.albumFontWeightSetting='';box.style.cssText='display:grid;gap:6px;margin-top:12px;min-width:0';const label=doc.createElement('label');label.textContent='폰트 굵기';label.htmlFor='album-font-weight';const select=doc.createElement('select');select.id='album-font-weight';select.setAttribute('aria-describedby','album-font-weight-note');select.style.cssText='min-height:44px;max-width:100%;font:inherit';for(const value of ['320','350','300']){const option=doc.createElement('option');option.value=value;option.textContent=value==='320'?'320 (기본)':value;select.append(option);}const note=doc.createElement('small');note.id='album-font-weight-note';note.textContent='사이트 전체 텍스트에 적용 · 이 브라우저에 자동 저장';const status=doc.createElement('p');status.className='hint';status.setAttribute('role','status');select.onchange=()=>{const result=set(select.value,owner);status.textContent=!result.applied?'계정이 변경되었습니다. 계정창을 다시 열어 주세요.':result.persisted?'':'현재 화면에는 적용했지만 브라우저 저장소를 사용할 수 없어 재접속 후 유지되지 않습니다.';};box.append(label,select,note,status);container.insertBefore(box,container.querySelector('#personal-status'));control={select,owner};apply();return box;}
 return {read,apply,set,mount};
}
